# --- Discord-safe text ---
# discord_post and discord_analysis splice digest_data / digest_analysis raw into
# {"content":"..."}, so a double quote, backslash, or control character in a rule
# name, agent name, or case title breaks that JSON and Discord rejects the post.
# Every line is cleaned once, where the lines are joined.
def clean(s):
    s = str(s).replace(chr(10), " ").replace(chr(13), " ").replace(chr(9), " ")
    s = s.replace(chr(92), "").replace(chr(34), chr(39))
    return "".join(c for c in s if ord(c) >= 32)

def clip_discord(s, limit=1950):
    # Lines are joined with a literal backslash-n; a cut between the backslash and
    # the n would leave a dangling escape that invalidates the Discord JSON body.
    if len(s) <= limit:
        return s
    return s[:limit - 3].rstrip(chr(92)) + "..."

